// Mayuri'z auto-post: new pieces on the live site -> Facebook Page + Instagram.
// Keys come from environment variables set by tools/run-n8n.ps1 (never stored here).
const SITE = 'https://mayurisyarntales.online/';
const G = 'https://graph.facebook.com/v23.0/';
const WAIT_MIN = 30;          // give the team time for /rename and /caption
const MAX_PER_RUN = 3;        // spread a big upload over several runs
const MAX_TRIES = 3;
const CHAT = $env.MZ_NOTE_CHAT || '-1003843804840';
const PAGE_ID = $env.META_PAGE_ID, PAGE_TOKEN = $env.META_PAGE_TOKEN, IG_ID = $env.META_IG_ID || '';
const IG_TOKEN = $env.META_IG_TOKEN || PAGE_TOKEN;   // Instagram uses its own system-user token
const DRY = $env.MZ_AUTOPOST_DRY === '1';
const http = this.helpers.httpRequest.bind(this.helpers);
const S = $getWorkflowStaticData('global');
S.seen = S.seen || {}; S.pending = S.pending || {}; S.tries = S.tries || {};
const now = Date.now();
const log = [];

const tag2hash = {
  Scrunchies: '#scrunchies #hairaccessories', Bows: '#crochetbow #hairbow', 'Claw Clips': '#clawclip #hairaccessories',
  'Hair Clips': '#hairclips #hairaccessories', 'Hair Pins': '#hairpins #hairaccessories', 'Hair Bands': '#hairband #hairaccessories',
  Roses: '#crochetrose #foreverflowers', Flowers: '#crochetflowers #foreverflowers', Garlands: '#crochetgarland #homedecor',
  Keychains: '#keychain #crochetkeychain', Charms: '#bagcharm #crochetcharm', Hearts: '#crochetheart #giftideas',
  Bookmarks: '#bookmark #booklover', Coasters: '#coasters #homedecor', Bangles: '#bangles #crochetjewellery', Bags: '#crochetbag #handmadebag',
};

async function note(text) {
  if (!$env.TELEGRAM_TOKEN) return;
  try {
    await http({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_TOKEN}/sendMessage`, json: true,
      body: { chat_id: CHAT, text, parse_mode: 'HTML', disable_web_page_preview: true } });
  } catch (e) { log.push('telegram note failed'); }
}
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const graphErr = e => e?.response?.body?.error?.message || e?.cause?.response?.data?.error?.message || e?.message || String(e);
async function graph(path, body, token = PAGE_TOKEN) {
  return http({ method: 'POST', url: G + path, json: true, body: { ...body, access_token: token } });
}

// Read  key: 'value'  from one product entry (handles \' inside the value).
function field(s, k) {
  const start = s.indexOf(k + ": '");
  if (start < 0) return '';
  let out = '';
  for (let i = start + k.length + 3; i < s.length; i++) {
    const ch = s[i];
    if (ch === '\\') { out += s[i + 1] || ''; i++; continue; }
    if (ch === "'") return out;
    out += ch;
  }
  return out;
}

// 1. read the product list from the live site
const html = String(await http({ url: `${SITE}index.html?t=${now}`, json: false }));
const block = html.split('/* PRODUCTS:START */')[1]?.split('/* PRODUCTS:END */')[0];
if (!block) throw new Error('PRODUCTS markers not found on the live site');
const products = block.split('{').slice(1).map(s => s.split('}')[0]).map(s => ({
  id: field(s, 'id'), sku: field(s, 'sku'), name: field(s, 'name'), tag: field(s, 'tag'), desc: field(s, 'desc'), image: field(s, 'image'),
})).filter(p => p.id && p.image);
if (products.length < 5) throw new Error(`Only ${products.length} products parsed - refusing to continue`);

// 2. first run: remember everything already in the shop, post nothing
if (!S.seeded) {
  for (const p of products) S.seen[p.id] = now;
  S.seeded = true;
  if (!DRY) await note(`🤖 <b>Auto-post is on</b>\nWatching ${products.length} pieces. New ones go to Facebook${IG_ID ? ' + Instagram' : ''} ${WAIT_MIN} min after they appear.`);
  return [{ json: { seeded: products.length, dry: DRY, first: products[0] } }];
}

// 3. new pieces that are named and have waited long enough
let posted = 0;
for (const p of products) {
  if (S.seen[p.id]) continue;
  if (p.name.toLowerCase().startsWith('new piece') || p.sku.includes('-NEW-')) { log.push(`${p.id}: waiting for a name`); continue; }
  if (!S.pending[p.id]) { S.pending[p.id] = now; log.push(`${p.id}: spotted, posting in ${WAIT_MIN} min`); continue; }
  if (now - S.pending[p.id] < WAIT_MIN * 60000) { log.push(`${p.id}: waiting`); continue; }
  if (posted >= MAX_PER_RUN) { log.push(`${p.id}: next run`); continue; }

  const img = SITE + p.image;
  const fbText = `${p.name}\n\n${p.desc}\n\nHandmade by Mayuri 🧶 Order: ${SITE}`;
  const igText = `${p.name} 🧶\n\n${p.desc}\n\nHandmade by Mayuri. Order through the link in our bio.\n\n#crochet #handmade #mayuriz ${tag2hash[p.tag] || '#crochetlove'}`;
  if (DRY) { log.push(`DRY ${p.id}: would post ${img}`); posted++; continue; }

  const done = [], failed = [];
  try { await graph(`${PAGE_ID}/photos`, { url: img, message: fbText }); done.push('Facebook'); }
  catch (e) { failed.push(`Facebook: ${graphErr(e)}`); }
  if (IG_ID) {
    try {
      const c = await graph(`${IG_ID}/media`, { image_url: img, caption: igText }, IG_TOKEN);
      let pub;
      for (let i = 0; i < 6 && !pub; i++) {
        await new Promise(r => setTimeout(r, 5000));
        try { pub = await graph(`${IG_ID}/media_publish`, { creation_id: c.id }, IG_TOKEN); } catch (e) { if (i === 5) throw e; }
      }
      done.push('Instagram');
    } catch (e) { failed.push(`Instagram: ${graphErr(e)}`); }
  }
  posted++;
  S.tries[p.id] = (S.tries[p.id] || 0) + 1;
  // Stop once anything went out (never double-post) or after MAX_TRIES failures.
  if (done.length || S.tries[p.id] >= MAX_TRIES) {
    S.seen[p.id] = now; delete S.pending[p.id]; delete S.tries[p.id];
  }
  if (done.length) await note(`📣 <b>Posted:</b> ${esc(p.name)}\n${done.join(' + ')} ✅`);
  if (failed.length) await note(`⚠️ <b>Couldn't post</b> ${esc(p.name)}\n${failed.map(esc).join('\n')}${S.seen[p.id] ? '' : '\nWill retry.'}`);
  log.push(`${p.id}: ${done.join('+') || 'none'}${failed.length ? ' | ' + failed.join('; ') : ''}`);
}
return [{ json: { checked: products.length, posted, dry: DRY, log } }];
